1	import { useState, useEffect } from 'react';
2	import { usePermissions } from '@/shared/hooks/usePermissions';
3	import { useAuth } from '@/shared/hooks/useAuth';
4	import { useNavigate } from 'react-router-dom';
5	import { supabase } from '@/integrations/supabase/client';
6	import {
7	  Card,
8	  CardContent,
9	  CardDescription,
10	  CardHeader,
11	  CardTitle,
12	} from '@/shared/ui/card';
13	import { Button } from '@/shared/ui/button';
14	import { Input } from '@/shared/ui/input';
15	import { Textarea } from '@/shared/ui/textarea';
16	import { Badge } from '@/shared/ui/badge';
17	import {
18	  Select,
19	  SelectContent,
20	  SelectItem,
21	  SelectTrigger,
22	  SelectValue,
23	} from '@/shared/ui/select';
24	import {
25	  Table,
26	  TableBody,
27	  TableCell,
28	  TableHead,
29	  TableHeader,
30	  TableRow,
31	} from '@/shared/ui/table';
32	import {
33	  Dialog,
34	  DialogContent,
35	  DialogDescription,
36	  DialogHeader,
37	  DialogTitle,
38	  DialogTrigger,
39	} from '@/shared/ui/dialog';
40	import { Alert, AlertDescription } from '@/shared/ui/alert';
41	import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
42	import { Checkbox } from '@/shared/ui/checkbox';
43	import { Switch } from '@/shared/ui/switch';
44	import { toast } from '@/shared/hooks/use-toast';
45	import {
46	  Users,
47	  Shield,
48	  Edit,
49	  Save,
50	  X,
51	  Trash2,
52	  CheckCircle,
53	  Clock,
54	  Building2,
55	  UserCheck,
56	  Settings,
57	} from 'lucide-react';
58	import { PermissionBlur } from '@/shared/ui/PermissionBlur';
59	import { wideInfo, wideError, wideWarn, wideDebug } from '@/shared/lib/telemetry/wide-events';
60	import { enrichWideEvent } from '@/shared/lib/telemetry/enrichWideEvent';
61	import { handleError } from '@/shared/lib/error-handler';
62	import { withTrace } from '@/shared/lib/telemetry/tracer';
63	import { recordOperation, recordOperationDuration, recordError } from '@/shared/lib/telemetry/metrics';
64	import { useTelemetryAttrs } from '@/shared/lib/telemetry/useTelemetryAttrs';
65	import { useFormTelemetry } from '@/shared/lib/telemetry/useFormTelemetry';
66	
67	import type {
68	  Employee,
69	  Role,
70	  Store,
71	  Permission,
72	  RolePermission,
73	} from '../types';
74	
75	export default function Usuarios() {
76	  const { user, loading: authLoading, refreshProfile } = useAuth();
77	  const { isAdmin, refreshPermissions, canAdminPermissions } = usePermissions();
